/* mapper/order_mapper.c: the only file including both headers */
int order_to_msg(const struct order *o, struct order_msg *m) {
    if (!o->id || !o->customer) return -1;
    m->id = o->id;                          /* borrowed: valid while the order lives */
    m->customer_id = o->customer->id;       /* reference flattened to an id          */
    m->total_minor = o->total_cents;        /* unit translation, deliberate          */
    return 0;
}
int order_from_msg(const struct order_msg *m, struct order *o) {
    return order_rehydrate(o, m->id, m->customer_id, m->total_minor);
}
